const vehicleRows = `-- name: VehicleRows :many
SELECT v.id, v.created_at, v.updated_at, v.registration_plate, v.status, v.account_id, v.current_battery_id,
  v.vehicle_model_id, v.hardware_id, v.vin, v.acquisition_path, v.petrol_engine_id, v.assigned_driver_id,
  v.qr_secret, v.iot_api_key_hash,
  m.make, m.model, m.vehicle_type, t.name AS battery_type_name,
  a.display_name AS owner_name, a.kura_id AS owner_kura_id, a.owner_user_id,
  b.serial AS battery_serial, b.charge_pct AS battery_charge, b.charge_source AS battery_charge_source,
  b.charge_observed_at AS battery_charge_at, b.health_pct AS battery_health,
  bt.usable_energy_wh AS battery_usable_wh, bt.wh_per_km AS battery_wh_per_km,
  du.first_name AS driver_first, du.last_name AS driver_last, du.phone AS driver_phone
FROM mobility_vehicle v
JOIN mobility_vehiclemodel m ON m.id = v.vehicle_model_id
JOIN mobility_batterytype t ON t.id = m.battery_type_id
JOIN accounts_account a ON a.id = v.account_id
LEFT JOIN mobility_battery b ON b.id = v.current_battery_id
LEFT JOIN mobility_batterytype bt ON bt.id = b.battery_type_id
LEFT JOIN accounts_driver d ON d.id = v.assigned_driver_id
LEFT JOIN accounts_user du ON du.id = d.user_id
WHERE v.id = ANY($1::uuid[])
`

type VehicleRowsRow struct {
	ID                  uuid.UUID
	CreatedAt           time.Time
	UpdatedAt           time.Time
	RegistrationPlate   string
	Status              string
	AccountID           uuid.UUID
	CurrentBatteryID    *uuid.UUID
	VehicleModelID      uuid.UUID
	HardwareID          *string
	Vin                 string
	AcquisitionPath     string
	PetrolEngineID      *uuid.UUID
	AssignedDriverID    *uuid.UUID
	QrSecret            string
	IotApiKeyHash       string
	Make                string
	Model               string
	VehicleType         string
	BatteryTypeName     string
	OwnerName           string
	OwnerKuraID         string
	OwnerUserID         uuid.UUID
	BatterySerial       *string
	BatteryCharge       *int32
	BatteryChargeSource *string
	BatteryChargeAt     *time.Time
	BatteryHealth       *int32
	BatteryUsableWh     *int32
	BatteryWhPerKm      *int32
	DriverFirst         *string
	DriverLast          *string
	DriverPhone         *string
}

func (q *Queries) VehicleRows(ctx context.Context, ids []uuid.UUID) ([]VehicleRowsRow, error) {
	rows, err := q.db.Query(ctx, vehicleRows, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []VehicleRowsRow{}
	for rows.Next() {
		var i VehicleRowsRow
		if err := rows.Scan(
			&i.ID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RegistrationPlate,
			&i.Status,
			&i.AccountID,
			&i.CurrentBatteryID,
			&i.VehicleModelID,
			&i.HardwareID,
			&i.Vin,
			&i.AcquisitionPath,
			&i.PetrolEngineID,
			&i.AssignedDriverID,
			&i.QrSecret,
			&i.IotApiKeyHash,
			&i.Make,
			&i.Model,
			&i.VehicleType,
			&i.BatteryTypeName,
			&i.OwnerName,
			&i.OwnerKuraID,
			&i.OwnerUserID,
			&i.BatterySerial,
			&i.BatteryCharge,
			&i.BatteryChargeSource,
			&i.BatteryChargeAt,
			&i.BatteryHealth,
			&i.BatteryUsableWh,
			&i.BatteryWhPerKm,
			&i.DriverFirst,
			&i.DriverLast,
			&i.DriverPhone,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

